spec.setup_code:
var names=['solar','wind','RoR+biomass','hard coal','CCGT gas','lignite','gas turbines','oil'];
var costs=[0,0,10,90,95,100,150,230];
var cols=['#E0A21B','#0B4FC0','#138374','#3D3D3D','#D0742B','#7B5534','#B4552F','#6A47C2'];
var base=[20,24,8,10,18,12,10,3];
var sunny=[45,34,8,10,18,12,10,3];
var calm=[0,6,8,10,18,12,10,3];
var titles=['Phase 1 · Building the stack','Phase 2 · Demand meets supply','Phase 3 · Sunny and windy noon','Phase 4 · Calm winter evening'];
function cl(x){return x<0?0:x>1?1:x;}
function ease(x){x=cl(x);return x*x*(3-2*x);}
function tbox(ctx,txt,x,y,col,font){
  ctx.font=font||'12px sans-serif';
  var tw=ctx.measureText(txt).width;
  ctx.fillStyle='rgba(255,255,255,0.88)';
  ctx.fillRect(x-3,y-12,tw+6,17);
  ctx.fillStyle=col;
  ctx.textAlign='left';
  ctx.fillText(txt,x,y);
}
return {draw:function(ctx,w,h,time,dt){
  ctx.globalAlpha=1;
  ctx.fillStyle='#ffffff';
  ctx.fillRect(0,0,w,h);
  var L=62,R=w-16,T=84,B=h-48,W=R-L,H=B-T;
  var px=function(x){return L+x/140*W;};
  var py=function(y){return T+(260-y)/280*H;};
  var ph=time%24;
  var k=Math.floor(ph/6);
  var lt=ph-6*k;
  var i;
  var a=k==2?ease((lt-0.3)/1.5):(k==3?1:0);
  var b=k==3?ease((lt-0.3)/1.5):0;
  var ws=[],x0=[],cum=0;
  for(i=0;i<8;i++){
    ws[i]=base[i]+(sunny[i]-base[i])*a+(calm[i]-sunny[i])*b;
    x0[i]=cum;cum+=ws[i];
  }
  var D=62,p=95;
  if(k==2){D=62-4*ease((lt-0.3)/1.5);p=95*(1-ease((lt-0.8)/1.4))-5*ease((lt-3.0)/0.8);}
  if(k==3){D=58+2*ease((lt-0.3)/1.5);p=-5+155*ease((lt-1.6)/0.9);}
  ctx.textAlign='left';
  ctx.font='bold 14px sans-serif';
  ctx.fillStyle='#04204B';
  ctx.fillText(titles[k],L-40,22);
  for(i=0;i<4;i++){
    ctx.beginPath();ctx.arc(w-70+i*16,18,4.5,0,6.2832);
    ctx.fillStyle=i==k?'#0B4FC0':'#c9d4e6';ctx.fill();
  }
  ctx.strokeStyle='#8098BC';ctx.lineWidth=1;
  ctx.setLineDash([3,4]);
  ctx.beginPath();ctx.moveTo(L,py(0));ctx.lineTo(R,py(0));ctx.stroke();
  ctx.setLineDash([]);
  ctx.strokeStyle='#04204B';ctx.lineWidth=1.2;
  ctx.beginPath();ctx.moveTo(L,T);ctx.lineTo(L,B);ctx.lineTo(R,B);ctx.stroke();
  ctx.font='12px sans-serif';ctx.fillStyle='#3D5F91';
  ctx.textAlign='center';
  for(i=0;i<=140;i+=20){
    ctx.beginPath();ctx.moveTo(px(i),B);ctx.lineTo(px(i),B+4);ctx.stroke();
    ctx.fillText(''+i,px(i),B+18);
  }
  ctx.fillText('capacity (GW)',L+W/2,B+36);
  ctx.textAlign='right';
  var yt=[-20,0,50,100,150,200,250];
  for(i=0;i<yt.length;i++){
    ctx.beginPath();ctx.moveTo(L-4,py(yt[i]));ctx.lineTo(L,py(yt[i]));ctx.stroke();
    ctx.fillText(''+yt[i],L-7,py(yt[i])+4);
  }
  ctx.save();ctx.translate(13,T+H/2);ctx.rotate(-Math.PI/2);
  ctx.textAlign='center';ctx.fillText('short-run marginal cost (EUR/MWh)',0,0);ctx.restore();
  ctx.save();ctx.beginPath();ctx.rect(L,T-4,W+2,H+4);ctx.clip();
  var ev=[],lastE=0;
  for(i=0;i<8;i++){
    ev[i]=k==0?ease((lt-(0.2+i*0.62))/0.6):1;
    if(ev[i]<=0||ws[i]<0.05)continue;
    var wpx=ws[i]/140*W;
    var xd=px(x0[i])-(1-ev[i])*(px(x0[i])-L+wpx);
    ctx.globalAlpha=ev[i];
    ctx.fillStyle=cols[i];
    ctx.fillRect(xd,py(costs[i]),wpx,py(-20)-py(costs[i]));
    ctx.strokeStyle='#ffffff';ctx.lineWidth=1;
    ctx.strokeRect(xd,py(costs[i]),wpx,py(-20)-py(costs[i]));
    if(ev[i]>0.5)lastE=x0[i]+ws[i];
  }
  ctx.globalAlpha=1;
  var rp=0;
  if(k==1)rp=ease((lt-2.6)/1.2);
  if(k==3)rp=ease((lt-3.0)/1.0);
  if(rp>0){
    for(i=0;i<8;i++){
      var xe=Math.min(x0[i]+ws[i],D);
      if(xe<=x0[i]||costs[i]>=p)continue;
      ctx.globalAlpha=0.3;
      ctx.fillStyle=cols[i];
      var yt2=py(costs[i]+(p-costs[i])*rp);
      ctx.fillRect(px(x0[i]),yt2,px(xe)-px(x0[i]),py(costs[i])-yt2);
    }
    ctx.globalAlpha=1;
  }
  ctx.restore();
  ctx.font='12px sans-serif';ctx.textAlign='left';
  for(i=0;i<8;i++){
    var wp=ws[i]/140*W;
    if(wp<10||ev[i]<0.8)continue;
    var txt=names[i]+' · '+costs[i]+' · '+Math.round(ws[i])+' GW';
    var tw=ctx.measureText(txt).width;
    var bh=py(-20)-py(costs[i]);
    var cx=px(x0[i])+wp/2;
    ctx.save();
    if(bh>=tw+14){
      ctx.translate(cx+4,py(-20)-8);ctx.fillStyle='#ffffff';
    }else{
      ctx.translate(cx+4,py(costs[i])-6);ctx.fillStyle='#04204B';
    }
    ctx.rotate(-Math.PI/2);
    ctx.fillText(txt,0,0);
    ctx.restore();
  }
  if(k>=1){
    var gr=k==1?ease(lt/0.9):1;
    ctx.strokeStyle='#04204B';ctx.lineWidth=2.2;
    ctx.beginPath();ctx.moveTo(px(D),T);ctx.lineTo(px(D),T+H*gr);ctx.stroke();
    if(gr>0.3)tbox(ctx,'demand '+Math.round(D)+' GW',px(D)+6,T+14,'#04204B','bold 12px sans-serif');
    var ma=k==1?ease((lt-0.9)/0.4):1;
    var fr=k==1?ease((lt-1.4)/1.2):1;
    if(ma>0){
      ctx.globalAlpha=ma;
      if(fr>0){
        ctx.strokeStyle='#B4552F';ctx.lineWidth=2;ctx.setLineDash([7,4]);
        ctx.beginPath();ctx.moveTo(px(D),py(p));ctx.lineTo(px(D)-(px(D)-L)*fr,py(p));ctx.stroke();
        ctx.setLineDash([]);
      }
      ctx.beginPath();ctx.arc(px(D),py(p),5.5,0,6.2832);
      ctx.fillStyle='#04204B';ctx.fill();
      ctx.strokeStyle='#ffffff';ctx.lineWidth=1.5;ctx.stroke();
      ctx.globalAlpha=1;
    }
    if(fr>=1){
      tbox(ctx,'clearing price '+Math.round(p)+' EUR/MWh',L+6,py(p)-7,'#B4552F','bold 12px sans-serif');
    }
  }
  var msg='',ma2=0;
  if(k==1){msg='inframarginal rent: every accepted seller gets 95';ma2=ease((lt-3.4)/0.6);}
  if(k==2){msg='price ~0 or negative: renewables set the price';ma2=ease((lt-3.4)/0.6);}
  if(k==3){msg='scarcity: a gas turbine sets the price';ma2=ease((lt-2.6)/0.6);}
  if(ma2>0){
    ctx.globalAlpha=ma2;ctx.textAlign='left';
    ctx.font='bold 13px sans-serif';ctx.fillStyle=k==1?'#0B4FC0':'#B4552F';
    ctx.fillText(msg,L,66);ctx.globalAlpha=1;
  }
  var st=['Sorted by rising cost; labels: name · EUR/MWh · GW. Stack so far: '+Math.round(lastE)+' GW',
    'Last accepted block (CCGT gas) sets the uniform price',
    'Solar '+Math.round(ws[0])+' GW + wind '+Math.round(ws[1])+' GW push the stack to the right',
    'Solar '+Math.round(ws[0])+' GW, wind '+Math.round(ws[1])+' GW: the stack shrinks, demand reaches the gas turbines'];
  ctx.font='12px sans-serif';ctx.fillStyle='#3D5F91';ctx.textAlign='left';
  ctx.fillText(st[k],L-40,42);
}};
